def cache_sim(capacity, ttl, ops):
    cache = {}
    lru_order = []
    results = []

    for op in ops:
        if op[0] == 'put':
            t, key, value = op[1], op[2], op[3]

            # Remove expired entries
            cache = {k: (v, wt) for k, (v, wt) in cache.items() if wt + ttl > t}
            lru_order = [k for k in lru_order if k in cache]

            # Remove key from lru_order if it exists
            if key in lru_order:
                lru_order.remove(key)

            # Evict LRU if necessary
            if key not in cache and len(cache) >= capacity:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            # Add/update the entry
            cache[key] = (value, t)
            lru_order.append(key)

        elif op[0] == 'get':
            t, key = op[1], op[2]

            # Remove expired entries
            cache = {k: (v, wt) for k, (v, wt) in cache.items() if wt + ttl > t}
            lru_order = [k for k in lru_order if k in cache]

            if key in cache:
                value, _ = cache[key]
                lru_order.remove(key)
                lru_order.append(key)
                results.append(value)
            else:
                results.append(-1)

    return results

